  <script>
    const body = document.body;
    const menuToggle = document.getElementById('menuToggle');
    const mainNav = document.getElementById('mainNav');

    menuToggle.addEventListener('click', () => {
      const isOpen = menuToggle.getAttribute('aria-expanded') === 'true';
      menuToggle.setAttribute('aria-expanded', String(!isOpen));
      menuToggle.setAttribute('aria-label', isOpen ? 'Open navigation menu' : 'Close navigation menu');
      mainNav.classList.toggle('active', !isOpen);
      body.classList.toggle('menu-open', !isOpen);
    });

    mainNav.querySelectorAll('a, button').forEach((item) => {
      item.addEventListener('click', () => {
        menuToggle.setAttribute('aria-expanded', 'false');
        menuToggle.setAttribute('aria-label', 'Open navigation menu');
        mainNav.classList.remove('active');
        body.classList.remove('menu-open');
      });
    });

    const modal = document.getElementById('donationModal');
    const donateTriggers = document.querySelectorAll('.donate-trigger');
    const closeModal = modal.querySelector('.close-modal');
    const amountOptions = modal.querySelectorAll('.amount-option');
    const impactMessage = document.getElementById('impactMessage');
    const customField = document.getElementById('customField');
    const customInput = customField.querySelector('input');
    let lastFocusedElement = null;

    function openModal() {
      lastFocusedElement = document.activeElement;
      modal.classList.add('active');
      body.classList.add('modal-open');
      closeModal.focus();
    }

    function closeDonationModal() {
      modal.classList.remove('active');
      body.classList.remove('modal-open');
      if (lastFocusedElement) lastFocusedElement.focus();
    }

    donateTriggers.forEach((trigger) => trigger.addEventListener('click', openModal));
    closeModal.addEventListener('click', closeDonationModal);
    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeDonationModal();
    });
    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && modal.classList.contains('active')) closeDonationModal();
    });

    amountOptions.forEach((option) => {
      option.addEventListener('click', () => {
        amountOptions.forEach((item) => item.classList.remove('active'));
        option.classList.add('active');
        const amount = option.dataset.amount;
        const impact = option.dataset.impact;
        customField.classList.toggle('active', amount === 'custom');
        if (amount === 'custom') {
          impactMessage.textContent = 'Your custom gift helps deliver urgent relief where it is needed most.';
          customInput.focus();
        } else {
          impactMessage.textContent = `Your $${amount} gift ${impact.charAt(0).toLowerCase()}${impact.slice(1)}.`;
        }
      });
    });

    customInput.addEventListener('input', () => {
      const amount = customInput.value;
      impactMessage.textContent = amount ? `Your $${amount} gift helps deliver urgent relief where it is needed most.` : 'Your custom gift helps deliver urgent relief where it is needed most.';
    });

    document.getElementById('continueDonation').addEventListener('click', () => {
      impactMessage.textContent = 'Thank you. This prototype is ready for a secure payment provider integration.';
    });

    const accordionTriggers = document.querySelectorAll('.accordion-trigger');
    function setPanelHeight(trigger) {
      const panel = document.getElementById(trigger.getAttribute('aria-controls'));
      panel.style.maxHeight = trigger.getAttribute('aria-expanded') === 'true' ? `${panel.scrollHeight}px` : '0px';
    }
    accordionTriggers.forEach((trigger) => {
      trigger.addEventListener('click', () => {
        const expanded = trigger.getAttribute('aria-expanded') === 'true';
        trigger.setAttribute('aria-expanded', String(!expanded));
        setPanelHeight(trigger);
      });
      setPanelHeight(trigger);
    });
    window.addEventListener('resize', () => accordionTriggers.forEach(setPanelHeight));

    const statNumbers = document.querySelectorAll('.stat-number');
    let statsAnimated = false;
    function animateStats() {
      if (statsAnimated) return;
      statsAnimated = true;
      statNumbers.forEach((stat) => {
        const target = Number(stat.dataset.count);
        const prefix = stat.dataset.prefix || '';
        const suffix = stat.dataset.suffix || '';
        const duration = 1200;
        const start = performance.now();
        function tick(now) {
          const progress = Math.min((now - start) / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const value = Math.round(target * eased);
          stat.textContent = `${prefix}${value}${suffix}`;
          if (progress < 1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      });
    }
    const impactObserver = new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting)) animateStats();
    }, { threshold: 0.35 });
    impactObserver.observe(document.getElementById('impact'));

    const track = document.getElementById('newsTrack');
    const prevNews = document.getElementById('prevNews');
    const nextNews = document.getElementById('nextNews');
    const carouselStatus = document.getElementById('carouselStatus');
    const cards = Array.from(track.children);
    let newsIndex = 0;

    function visibleCount() {
      if (window.innerWidth <= 760) return 1;
      if (window.innerWidth <= 1020) return 2;
      return 3;
    }

    function updateCarousel() {
      const count = visibleCount();
      const maxIndex = Math.max(cards.length - count, 0);
      newsIndex = Math.min(newsIndex, maxIndex);
      const cardWidth = cards[0].getBoundingClientRect().width;
      const gap = parseFloat(getComputedStyle(track).gap) || 0;
      track.style.transform = `translateX(-${newsIndex * (cardWidth + gap)}px)`;
      prevNews.disabled = newsIndex === 0;
      nextNews.disabled = newsIndex === maxIndex;
      carouselStatus.textContent = `Showing news stories ${newsIndex + 1}–${Math.min(newsIndex + count, cards.length)} of ${cards.length}`;
    }

    prevNews.addEventListener('click', () => {
      newsIndex = Math.max(newsIndex - 1, 0);
      updateCarousel();
    });
    nextNews.addEventListener('click', () => {
      newsIndex += 1;
      updateCarousel();
    });
    window.addEventListener('resize', updateCarousel);
    updateCarousel();
  </script>
</body>
</html>
