      --red-dark: #9f1730;
      --navy: #1b3a5c;
      --navy-dark: #10263f;
      --cream: #fff8f2;
      --white: #ffffff;
      --gray-25: #fcfbfa;
      --gray-50: #f7f4f1;
      --gray-100: #ece7e2;
      --gray-300: #cfc6bd;
      --gray-600: #665d56;
      --gray-800: #2c2825;
      --shadow: 0 18px 45px rgba(27, 58, 92, 0.16);
      --shadow-soft: 0 10px 30px rgba(27, 58, 92, 0.1);
      --radius: 22px;
      --max: 1180px;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--gray-800);
      background: var(--gray-25);
      line-height: 1.6;
      text-rendering: optimizeLegibility;
    }

    body.menu-open, body.modal-open { overflow: hidden; }
    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    button, input { font: inherit; }
    button { cursor: pointer; }

    .skip-link {
      position: fixed;
      top: -80px;
      left: 16px;
      z-index: 1000;
      padding: 12px 16px;
      color: var(--white);
      background: var(--navy);
      border-radius: 999px;
      transition: top 0.2s ease;
    }
    .skip-link:focus { top: 16px; }

    .container {
      width: min(100% - 40px, var(--max));
      margin-inline: auto;
    }

    .topbar {
      color: var(--white);
      background: var(--navy-dark);
      font-size: 0.88rem;
    }
    .topbar .container {
      display: flex;
      justify-content: flex-end;
      gap: 18px;
      padding: 8px 0;
    }
    .topbar a { opacity: 0.9; }
    .topbar a:hover, .topbar a:focus { opacity: 1; text-decoration: underline; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255, 255, 255, 0.96);
      backdrop-filter: blur(14px);
      border-bottom: 1px solid var(--gray-100);
    }
    .nav-wrap {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      min-height: 78px;
    }
    .brand {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      min-width: max-content;
      font-weight: 850;
      color: var(--navy);
      letter-spacing: -0.03em;
      font-size: 1.18rem;
    }
    .brand-mark {
      display: grid;
      place-items: center;
      width: 46px;
      height: 46px;
      color: var(--white);
      background: var(--red);
      border-radius: 14px;
      box-shadow: 0 10px 20px rgba(196, 30, 58, 0.24);
    }
    .brand small {
      display: block;
      margin-top: -4px;
      color: var(--gray-600);
      font-size: 0.72rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }
    .main-nav {
      display: flex;
      align-items: center;
      gap: 20px;
      margin-left: auto;
      color: var(--navy-dark);
      font-size: 0.94rem;
      font-weight: 750;
    }
    .main-nav a:not(.btn) {
      padding: 10px 0;
      border-bottom: 2px solid transparent;
    }
    .main-nav a:not(.btn):hover, .main-nav a:not(.btn):focus {
      color: var(--red);
      border-color: var(--red);
    }
    .hamburger {
      display: none;
      width: 48px;
      height: 48px;
      border: 1px solid var(--gray-100);
      border-radius: 14px;
      background: var(--white);
      color: var(--navy);
    }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      margin: 5px auto;
      background: currentColor;
      transition: transform 0.2s ease, opacity 0.2s ease;
    }
    .hamburger[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
    .hamburger[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      min-height: 46px;
      padding: 12px 20px;
      border: 0;
      border-radius: 999px;
      font-weight: 850;
      transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
      white-space: nowrap;
    }
    .btn:hover, .btn:focus { transform: translateY(-2px); }
    .btn-primary {
      color: var(--white);
      background: var(--red);
      box-shadow: 0 12px 25px rgba(196, 30, 58, 0.24);
    }
    .btn-primary:hover, .btn-primary:focus { background: var(--red-dark); }
    .btn-secondary {
      color: var(--navy);
      background: var(--white);
      border: 1px solid rgba(27, 58, 92, 0.14);
      box-shadow: var(--shadow-soft);
    }
    .btn-navy {
      color: var(--white);
      background: var(--navy);
    }
    .btn-outline {
      color: var(--red);
      background: transparent;
      border: 1px solid rgba(196, 30, 58, 0.32);
    }

    .hero {
      position: relative;
      overflow: hidden;
      padding: 78px 0 68px;
      background:
        radial-gradient(circle at 85% 12%, rgba(196, 30, 58, 0.16), transparent 28%),
        linear-gradient(135deg, #fff 0%, #fff8f2 54%, #eef4f9 100%);
    }
    .hero::before {
      content: "";
      position: absolute;
      inset: 0;
      background-image: linear-gradient(rgba(27,58,92,0.045) 1px, transparent 1px), linear-gradient(90deg, rgba(27,58,92,0.045) 1px, transparent 1px);
      background-size: 44px 44px;
      mask-image: linear-gradient(90deg, #000, transparent 78%);
      pointer-events: none;
    }
    .hero-grid {
      position: relative;
      display: grid;
      grid-template-columns: 1.02fr 0.98fr;
      gap: 54px;
      align-items: center;
    }
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin: 0 0 18px;
      color: var(--red-dark);
      font-size: 0.82rem;
      font-weight: 900;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }
    .eyebrow::before {
      content: "";
      width: 34px;
      height: 3px;
      background: var(--red);
      border-radius: 999px;
    }
    h1, h2, h3 {
      margin: 0;
      color: var(--navy-dark);
      line-height: 1.05;
      letter-spacing: -0.055em;
    }
    h1 {
      max-width: 11ch;
      font-size: clamp(3.15rem, 7vw, 6.5rem);
    }
    h2 { font-size: clamp(2.15rem, 4vw, 3.55rem); }
    h3 { font-size: 1.3rem; letter-spacing: -0.035em; }
    .hero p {
      max-width: 640px;
      margin: 24px 0 0;
      color: var(--gray-600);
      font-size: clamp(1.08rem, 2vw, 1.28rem);
    }
    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-top: 34px;
    }
    .hero-note {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 24px;
      color: var(--navy);
      font-weight: 800;
    }
    .pulse-dot {
      width: 12px;
      height: 12px;
      background: #28a745;
      border-radius: 50%;
      box-shadow: 0 0 0 8px rgba(40, 167, 69, 0.12);
    }
    .hero-card {
      position: relative;
      min-height: 560px;
      border-radius: 34px;
      overflow: hidden;
      background: var(--navy);
      box-shadow: var(--shadow);
    }
    .hero-card img {
      width: 100%;
      height: 100%;
      min-height: 560px;
      object-fit: cover;
      opacity: 0.82;
      filter: saturate(0.9) contrast(1.02);
    }
    .hero-card::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 38%, rgba(16, 38, 63, 0.82));
    }
    .response-card {
      position: absolute;
      left: 24px;
      right: 24px;
      bottom: 24px;
      z-index: 1;
      padding: 24px;
      color: var(--white);
      background: rgba(16, 38, 63, 0.82);
      border: 1px solid rgba(255,255,255,0.18);
      border-radius: 24px;
      backdrop-filter: blur(12px);
    }
    .response-card strong { display: block; font-size: 1.25rem; }
    .response-card span { color: rgba(255,255,255,0.82); }

    section { padding: 86px 0; }
    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 28px;
      margin-bottom: 38px;
    }
    .section-head p {
      max-width: 610px;
      margin: 0;
      color: var(--gray-600);
      font-size: 1.05rem;
    }

    .mission-grid {
      display: grid;
      grid-template-columns: 0.85fr 1.15fr;
      gap: 38px;
      align-items: stretch;
    }
    .mission-aside {
      padding: 34px;
      color: var(--white);
      background: var(--navy);
      border-radius: var(--radius);
      box-shadow: var(--shadow-soft);
    }
    .mission-aside strong {
      display: block;
      font-size: clamp(1.75rem, 3vw, 2.6rem);
      line-height: 1.08;
      letter-spacing: -0.05em;
    }
    .mission-aside span {
      display: inline-block;
      margin-top: 22px;
      color: rgba(255,255,255,0.82);
      font-weight: 750;
    }
    .mission-copy {
      padding: 36px;
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: var(--radius);
    }
    .mission-copy p { margin: 0; color: var(--gray-600); font-size: 1.07rem; }
    .mission-copy p + p { margin-top: 18px; }
    .principles {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 26px;
    }
    .principles span {
      padding: 8px 12px;
      color: var(--navy);
      background: var(--gray-50);
      border-radius: 999px;
      font-weight: 850;
      font-size: 0.9rem;
    }

    .impact {
      color: var(--white);
      background: linear-gradient(135deg, var(--navy-dark), var(--navy));
    }
    .impact h2, .impact .eyebrow { color: var(--white); }
    .impact .eyebrow::before { background: var(--white); }
    .impact .section-head p { color: rgba(255,255,255,0.78); }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 18px;
    }
    .stat-card {
      min-height: 178px;
      padding: 26px;
      background: rgba(255,255,255,0.09);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 24px;
    }
    .stat-number {
      display: block;
      color: var(--white);
      font-size: clamp(2.1rem, 4vw, 3.35rem);
      font-weight: 950;
      line-height: 1;
      letter-spacing: -0.07em;
    }
    .stat-label {
      display: block;
      margin-top: 14px;
      color: rgba(255,255,255,0.82);
      font-weight: 760;
    }

    .programs { background: var(--gray-50); }
    .accordion {
      display: grid;
      gap: 14px;
    }
    .accordion-item {
      overflow: hidden;
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: 20px;
      box-shadow: 0 7px 18px rgba(27, 58, 92, 0.04);
    }
    .accordion-trigger {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      width: 100%;
      min-height: 76px;
      padding: 22px 24px;
      color: var(--navy-dark);
      background: transparent;
      border: 0;
      text-align: left;
      font-weight: 900;
      font-size: 1.1rem;
    }
    .accordion-trigger span:first-child {
      display: inline-flex;
      align-items: center;
      gap: 14px;
    }
    .program-icon {
      display: grid;
      place-items: center;
      width: 42px;
      height: 42px;
      color: var(--red);
      background: rgba(196, 30, 58, 0.09);
      border-radius: 14px;
      flex: 0 0 auto;
    }
    .accordion-icon {
      display: grid;
      place-items: center;
      width: 34px;
      height: 34px;
      color: var(--navy);
      background: var(--gray-50);
      border-radius: 50%;
      transition: transform 0.24s ease;
      flex: 0 0 auto;
    }
    .accordion-trigger[aria-expanded="true"] .accordion-icon { transform: rotate(45deg); }
    .accordion-panel {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.32s ease;
    }
    .accordion-panel-inner {
      padding: 0 24px 24px 80px;
      color: var(--gray-600);
    }
    .text-link {
      display: inline-flex;
      margin-top: 14px;
      color: var(--red);
      font-weight: 900;
    }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .involved-card {
      display: flex;
      min-height: 305px;
      flex-direction: column;
      padding: 28px;
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: 24px;
      box-shadow: var(--shadow-soft);
    }
    .involved-card img {
      width: 100%;
      height: 150px;
      object-fit: cover;
      margin-bottom: 22px;
      border-radius: 18px;
      background: var(--gray-100);
    }
    .involved-card p { color: var(--gray-600); }
    .involved-card .btn { margin-top: auto; align-self: start; }

    .news { background: var(--white); }
    .carousel-shell { position: relative; }
    .carousel-viewport { overflow: hidden; }
    .news-track {
      display: flex;
      gap: 20px;
      transition: transform 0.35s ease;
      will-change: transform;
    }
    .news-card {
      flex: 0 0 calc((100% - 40px) / 3);
      overflow: hidden;
      background: var(--gray-25);
      border: 1px solid var(--gray-100);
      border-radius: 24px;
      box-shadow: 0 12px 28px rgba(27,58,92,0.07);
    }
    .news-card img {
      width: 100%;
      height: 190px;
      object-fit: cover;
      background: var(--gray-100);
    }
    .news-body { padding: 24px; }
    .news-body time {
      color: var(--red);
      font-size: 0.83rem;
      font-weight: 900;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }
    .news-body h3 { margin-top: 8px; }
    .news-body p { color: var(--gray-600); }
    .carousel-controls {
      display: flex;
      gap: 10px;
      justify-content: flex-end;
      margin-top: 24px;
    }
    .carousel-btn {
      display: grid;
      place-items: center;
      width: 48px;
      height: 48px;
      color: var(--navy);
      background: var(--white);
      border: 1px solid var(--gray-100);
      border-radius: 50%;
      box-shadow: var(--shadow-soft);
    }
    .carousel-btn:disabled {
      opacity: 0.45;
      cursor: not-allowed;
      transform: none;
    }
    .carousel-status {
      margin-top: 10px;
      color: var(--gray-600);
      font-size: 0.92rem;
      text-align: right;
    }

    .donate-cta {
      background: linear-gradient(135deg, rgba(196,30,58,0.08), rgba(27,58,92,0.08));
    }
    .donate-panel {
      display: grid;
      grid-template-columns: 0.9fr 1.1fr;
      gap: 34px;
      align-items: center;
      padding: clamp(28px, 5vw, 52px);
      background: var(--white);
      border-radius: 34px;
      box-shadow: var(--shadow);
    }
    .donate-panel p { color: var(--gray-600); font-size: 1.08rem; }
    .amount-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
    }
    .amount-impact {
      padding: 18px;
      background: var(--gray-50);
      border: 1px solid var(--gray-100);
      border-radius: 18px;
    }
    .amount-impact strong {
      display: block;
      color: var(--red);
      font-size: 1.35rem;
    }
    .amount-impact span { color: var(--gray-600); font-size: 0.93rem; }

    .site-footer {
      padding: 62px 0 28px;
      color: rgba(255,255,255,0.78);
      background: var(--navy-dark);
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 1.3fr repeat(4, 1fr);
      gap: 30px;
    }
    .footer-brand { color: var(--white); }
    .footer-brand p { max-width: 280px; color: rgba(255,255,255,0.72); }
    .footer-col h3 {
      color: var(--white);
      margin-bottom: 14px;
      font-size: 1rem;
      letter-spacing: -0.02em;
    }
    .footer-col a {
      display: block;
      margin: 9px 0;
      color: rgba(255,255,255,0.74);
    }
    .footer-col a:hover, .footer-col a:focus { color: var(--white); text-decoration: underline; }
    .footer-bottom {
      display: flex;
      justify-content: space-between;
      gap: 20px;
      margin-top: 44px;
      padding-top: 24px;
      border-top: 1px solid rgba(255,255,255,0.12);
      font-size: 0.9rem;
    }
    .socials { display: flex; flex-wrap: wrap; gap: 12px; }

    .modal-backdrop {
      position: fixed;
      inset: 0;
      z-index: 500;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 20px;
      background: rgba(16, 38, 63, 0.68);
    }
    .modal-backdrop.active { display: flex; }
    .donation-modal {
      width: min(100%, 620px);
      max-height: min(92vh, 760px);
      overflow: auto;
      background: var(--white);
      border-radius: 28px;
      box-shadow: 0 25px 80px rgba(0,0,0,0.3);
      animation: modalIn 0.2s ease both;
    }
    @keyframes modalIn {
      from { opacity: 0; transform: translateY(18px) scale(0.98); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }
    .modal-header {
      display: flex;
      justify-content: space-between;
      gap: 16px;
      padding: 28px 28px 18px;
      border-bottom: 1px solid var(--gray-100);
    }
    .modal-header p { margin: 8px 0 0; color: var(--gray-600); }
    .close-modal {
      display: grid;
      place-items: center;
      width: 44px;
      height: 44px;
      flex: 0 0 auto;
      color: var(--navy);
      background: var(--gray-50);
      border: 0;
      border-radius: 50%;
      font-size: 1.5rem;
    }
    .modal-body { padding: 24px 28px 28px; }
    .donation-options {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin: 12px 0 20px;
    }
    .amount-option {
      min-height: 62px;
      padding: 12px;
      color: var(--navy);
      background: var(--white);
      border: 2px solid var(--gray-100);
      border-radius: 16px;
      font-weight: 950;
    }
    .amount-option.active {
      color: var(--white);
      background: var(--red);
      border-color: var(--red);
    }
    .custom-field { display: none; margin-bottom: 18px; }
    .custom-field.active { display: block; }
    .custom-field input {
      width: 100%;
      min-height: 50px;
      padding: 12px 14px;
      border: 1px solid var(--gray-300);
      border-radius: 14px;
    }
    .impact-message {
      padding: 16px;
      color: var(--navy);
      background: #f9f1e8;
      border-radius: 16px;
      font-weight: 800;
    }
    .modal-actions {
      display: grid;
      gap: 10px;
      margin-top: 20px;
    }
    .secure-note { color: var(--gray-600); font-size: 0.9rem; text-align: center; }

    :focus-visible {
      outline: 3px solid rgba(196, 30, 58, 0.45);
      outline-offset: 3px;
    }

    @media (max-width: 1020px) {
      .hamburger { display: block; }
      .main-nav {
        position: fixed;
        top: 126px;
        right: 16px;
        left: 16px;
        display: grid;
        gap: 4px;
        padding: 18px;
        background: var(--white);
        border: 1px solid var(--gray-100);
        border-radius: 22px;
        box-shadow: var(--shadow);
        transform: translateY(-16px);
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        transition: transform 0.24s ease, opacity 0.24s ease, visibility 0.24s ease;
      }
      .main-nav.active {
        transform: translateY(0);
        opacity: 1;
        visibility: visible;
        pointer-events: auto;
      }
      .main-nav a:not(.btn) { padding: 13px 10px; border: 0; }
      .main-nav .btn { margin-top: 8px; }
      .hero-grid, .mission-grid, .donate-panel { grid-template-columns: 1fr; }
      .hero-card, .hero-card img { min-height: 420px; }
      .stats-grid, .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-brand { grid-column: 1 / -1; }
      .news-card { flex-basis: calc((100% - 20px) / 2); }
    }

    @media (max-width: 760px) {
      .container { width: min(100% - 28px, var(--max)); }
      .topbar .container { justify-content: center; }
      .brand { font-size: 1rem; }
      .brand-mark { width: 42px; height: 42px; }
      .hero { padding: 54px 0 46px; }
      h1 { font-size: clamp(2.8rem, 14vw, 4.2rem); }
      section { padding: 62px 0; }
      .section-head { display: block; }
      .section-head p { margin-top: 14px; }
      .hero-actions .btn { width: 100%; }
      .hero-card, .hero-card img { min-height: 360px; }
      .response-card { left: 14px; right: 14px; bottom: 14px; padding: 18px; }
      .stats-grid, .involved-grid, .amount-grid, .footer-grid, .donation-options { grid-template-columns: 1fr; }
      .accordion-trigger { align-items: flex-start; padding: 18px; }
      .accordion-panel-inner { padding: 0 18px 20px 18px; }
      .news-card { flex-basis: 100%; }
      .footer-bottom { display: block; }
      .socials { margin-top: 14px; }
      .modal-header, .modal-body { padding-inline: 20px; }
    }

    @media (prefers-reduced-motion: reduce) {
